// DecodeExportRequest returns a decoder for requests sent to the settings
// export endpoint.
func DecodeExportRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*settings.ExportPayload, error) {
	return func(r *http.Request) (*settings.ExportPayload, error) {
		var payload *settings.ExportPayload
		var (
			targetKind string
			targetID   int64
			cookie     string
			err        error
		)
		qp := r.URL.Query()
		targetKindRaw := qp.Get("targetKind")
		if targetKindRaw != "" {
			targetKind = targetKindRaw
		} else {
			targetKind = "workspace"
		}
		if !(targetKind == "workspace") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("targetKind", targetKind, []any{"workspace"}))
		}
		{
			targetIDRaw := qp.Get("targetId")
			if targetIDRaw != "" {
				v, err2 := strconv.ParseInt(targetIDRaw, 10, 64)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("targetId", targetIDRaw, "integer"))
				}
				targetID = v
			}
		}
		if targetID < 0 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("targetId", targetID, 0, true))
		}
		if targetID > 0 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("targetId", targetID, 0, false))
		}
		cookie = r.Header.Get("Cookie")
		if cookie == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("cookie", "header"))
		}
		if err != nil {
			return payload, err
		}
		payload = NewExportPayload(targetKind, targetID, cookie)
		if index := strings.IndexByte(string(payload.Cookie), ' '); index >= 0 {
			// Remove authorization scheme prefix (e.g. "Bearer")
			payload.Cookie = payload.Cookie[index+1:]
		}

		return payload, nil
	}
}

