// marshalSettingsConfigDefinitionToConfigDefinitionResponseBody builds a value
// of type *ConfigDefinitionResponseBody from a value of type
// *settings.ConfigDefinition.
func marshalSettingsConfigDefinitionToConfigDefinitionResponseBody(v *settings.ConfigDefinition) *ConfigDefinitionResponseBody {
	res := &ConfigDefinitionResponseBody{
		Key:          v.Key,
		Group:        v.Group,
		Kind:         v.Kind,
		DefaultValue: v.DefaultValue,
		Sensitive:    v.Sensitive,
		Secret:       v.Secret,
	}
	if v.Scopes != nil {
		res.Scopes = make([]string, len(v.Scopes))
		for i, val := range v.Scopes {
			res.Scopes[i] = val
		}
	} else {
		res.Scopes = []string{}
	}
	if v.Choices != nil {
		res.Choices = make([]string, len(v.Choices))
		for i, val := range v.Choices {
			res.Choices[i] = val
		}
	} else {
		res.Choices = []string{}
	}

	return res
}

